3|import React, { useState, useRef, useCallback, useEffect } from "react";
4|import BaseNode from "./BaseNode";
5|import type { NodeProps } from "@xyflow/react";
6|import type { NodeData } from "@/types/workflow";
7|import { useSettingsStore } from "@/stores/settingsStore";
8|import { useWorkflowStore } from "@/stores/workflowStore";
9|import { uploadAsset } from "@/lib/assetUpload";
10|import PreviewModal from "@/components/PreviewModal";
11|import VideoPreview from "@/components/VideoPreview";
12|import MentionInput from "@/components/MentionInput";
13|import { proxyUrl } from "@/lib/mediaProxy";
14|
15|// 已验证的视频模型
16|const VIDEO_MODELS = [
17|  "seedance-2",
18|];
19|
20|// 模型支持的时长选项
21|const MODEL_DURATIONS: Record<string, number[]> = {
22|  "seedance-2": [5, 10],
23|};
24|
25|// 获取当前模型支持的时长选项
26|const getSupportedDurations = (model: string): number[] => {
27|  return MODEL_DURATIONS[model] || [5];
28|};
29|
30|// 视频比例/尺寸
31|const VIDEO_RATIOS = [
32|  { label: "9:16 竖版", value: "9:16" },
33|  { label: "3:4 竖版", value: "3:4" },
34|  { label: "1:1 方版", value: "1:1" },
35|  { label: "16:9 横版", value: "16:9" },
36|];
37|
38|// 视频清晰度
39|const VIDEO_RESOLUTIONS = [
40|  { label: "480p", value: "480p" },
41|  { label: "720p", value: "720p" },
42|  { label: "1080p", value: "1080p" },
43|];
44|
45|export default function VideoNode(props: NodeProps) {
46|  const d = props.data as unknown as NodeData;
47|  const cfg = d.config as {
48|    content?: string;
49|    model?: string;
50|    ratio?: string;
51|    resolution?: string;
52|    duration?: number;
53|    assetUrl?: string;
54|    assetId?: string;
55|    assetName?: string;
56|  };
57|
58|  const { videoApi } = useSettingsStore();
59|  const { nodes, edges, updateNodeData, selectedNodeId, selectNodeQuietly, setShowControlPanel } = useWorkflowStore();
60|
61|  const [prompt, setPrompt] = useState(cfg.content ?? "");
62|  const [model, setModel] = useState(cfg.model ?? VIDEO_MODELS[0]);
63|  const [ratio, setRatio] = useState(cfg.ratio ?? VIDEO_RATIOS[0].value);
64|  const [resolution, setResolution] = useState(cfg.resolution ?? VIDEO_RESOLUTIONS[1].value);
65|  const [duration, setDuration] = useState(cfg.duration ?? getSupportedDurations(cfg.model ?? VIDEO_MODELS[0])[0]);
66|  
67|  // 模型切换时自动调整duration
68|  useEffect(() => {
69|    const supported = getSupportedDurations(model);
70|    if (!supported.includes(duration)) {
71|      setDuration(supported[0]);
72|    }
73|  }, [model]);
74|
75|  // 根据ratio计算预览框高度（基础宽度280px）
76|  const getPreviewHeight = (ratio: string) => {
77|    const [w, h] = ratio.split(':').map(Number);
78|    return Math.round(280 * h / w);
79|  };
80|  const previewHeight = getPreviewHeight(ratio);
81|  const [previewUrl, setPreviewUrl] = useState(cfg.assetUrl ?? null);
82|  const [error, setError] = useState<string | null>(null);
83|  const [loading, setLoading] = useState(false);
84|  const [progress, setProgress] = useState(0);
85|  const [showPreview, setShowPreview] = useState(false);
86|  // 只有当前节点被选中时才显示控制面板
87|  const showControls = selectedNodeId === props.id;
88|  const [dragOver, setDragOver] = useState(false);
89|  const fileInputRef = useRef<HTMLInputElement>(null);
90|  const pollRef = useRef<NodeJS.Timeout | null>(null);
91|
92|  // 获取上游连接的素材（组件级别）
93|  // 参考TapNow逻辑：遍历所有入边，收集所有连接的素材
94|  const getUpstreamAssets = useCallback(() => {
95|    const incomingEdges = edges.filter((e) => e.target === props.id);
96|    const assets: { 
97|      images: Array<{ url: string; assetId: string; assetName: string }>; 
98|      videos: Array<{ url: string; assetId: string; assetName: string }> 
99|    } = { images: [], videos: [] };
100|
101|    // 遍历所有入边
102|    for (const edge of incomingEdges) {
103|      const sourceNode = nodes.find((n) => n.id === edge.source);
104|      if (!sourceNode) continue;
105|      
106|      const nodeData = sourceNode.data as unknown as NodeData;
107|      const url = nodeData.assetUrl || (nodeData.config as any)?.assetUrl;
108|      const assetId = nodeData.assetId || (nodeData.config as any)?.assetId;
109|      const assetName = nodeData.assetName || (nodeData.config as any)?.assetName || "素材";
110|      const nodeType = nodeData.nodeType || (nodeData.config as any)?.nodeType;
111|
112|      // 根据节点类型分类
113|      if (nodeType === "IMAGE") {
114|        assets.images.push({ url: url || "", assetId: assetId || "", assetName });
115|      } else if (nodeType === "VIDEO") {
116|        assets.videos.push({ url: url || "", assetId: assetId || "", assetName });
117|      }
118|    }
119|
120|    return assets;
121|  }, [edges, nodes, props.id]);
122|
123|  // 获取上游素材（组件级别，用于@提及）
124|  const upstream = getUpstreamAssets();
125|
126|  const updateResult = useCallback((url: string, assetId: string) => {
127|    setPreviewUrl(url);
128|    updateNodeData(props.id, {
129|      status: "success",
130|      assetType: "VIDEO" as const,
131|      assetUrl: url,
132|      assetId,
133|      config: { ...cfg, assetUrl: url, assetId },
134|    });
135|  }, [props.id, cfg, updateNodeData]);
136|
137|  // 处理文件上传
138|  const handleFileUpload = async (file: File) => {
139|    if (!file.type.startsWith("video/")) {
140|      setError("请上传视频文件");
141|      return;
142|    }
143|
144|    setError(null);
145|    setLoading(true);
146|    setProgress(0);
147|
148|    try {
149|      const result = await uploadAsset(file, videoApi.apiKey, (p) => setProgress(p));
150|      if (result.success && result.url) {
151|        updateResult(result.url, result.assetId || "");
152|      } else {
153|        setError(result.error || "上传失败");
154|      }
155|    } catch (e) {
156|      setError(e instanceof Error ? e.message : "上传出错");
157|    } finally {
158|      setLoading(false);
159|    }
160|  };
161|
162|  // AI 生成视频
163|  const handleGenerate = async () => {
164|    if (!prompt.trim()) {
165|      setError("请输入提示词");
166|      return;
167|    }
168|    if (!videoApi.apiUrl || !videoApi.apiKey) {
169|      setError("请先在设置中配置 API");
170|      return;
171|    }
172|
173|    setError(null);
174|    setLoading(true);
175|    setProgress(0);
176|    updateNodeData(props.id, { status: "running", progress: 0 });
177|
178|    try {
179|      // 获取上游素材
180|      const upstream = getUpstreamAssets();
181|      
182|      // 构造带素材名称和顺序的提示词
183|      // 参考TapNow：在提示词中明确每个素材的编号
184|      let fullPrompt = prompt;
185|      const refs: string[] = [];
186|      let idx = 1;
187|      upstream.images.forEach((img) => {
188|        refs.push(`[素材${idx}: ${img.assetName}]`);
189|        idx++;
190|      });
191|      upstream.videos.forEach((vid) => {
192|        refs.push(`[素材${idx}: ${vid.assetName}]`);
193|        idx++;
194|      });
195|      if (refs.length > 0) {
196|        fullPrompt = `${refs.join(' ')}
197|${prompt}`;
198|      }
199|      
200|      // 收集所有有效的素材URL
201|      const imageUrls = upstream.images.filter(img => img.url).map(img => img.url);
202|      const videoUrls = upstream.videos.filter(vid => vid.url).map(vid => vid.url);
203|      
204|      const resp = await fetch("http://localhost:8000/api/generate/video", {
205|        method: "POST",
206|        headers: { "Content-Type": "application/json" },
207|        body: JSON.stringify({
208|          prompt: fullPrompt,
209|          api_url: videoApi.apiUrl,
210|          api_key: videoApi.apiKey,
211|          model,
212|          resolution: resolution,
213|          ratio: ratio,
214|          reference_image_urls: imageUrls.length > 0 ? imageUrls : undefined,
215|          reference_video_urls: videoUrls.length > 0 ? videoUrls : undefined,
216|          duration,
217|        }),
218|      });
219|
220|      if (!resp.ok) {
221|        const err = await resp.json();
222|        throw new Error(err.detail || "创建任务失败");
223|      }
224|
225|      const data = await resp.json();
226|      if (data.task_id) {
227|        // 轮询任务状态
228|        pollRef.current = setInterval(async () => {
229|          try {
230|            const pollResp = await fetch(
231|              `http://localhost:8000/api/generate/task/video/${data.task_id}?api_url=${encodeURIComponent(videoApi.apiUrl)}&api_key=${encodeURIComponent(videoApi.apiKey)}`
232|            );
233|            if (!pollResp.ok) return;
234|            const pollData = await pollResp.json();
235|            setProgress(pollData.progress || 0);
236|
237|            if (pollData.status === "completed" && pollData.url) {
238|              clearInterval(pollRef.current!);
239|              updateResult(pollData.url, pollData.asset_id || "");
240|              setLoading(false);
241|            } else if (pollData.status === "failed") {
242|              clearInterval(pollRef.current!);
243|              setError(pollData.error || "生成失败");
244|              setLoading(false);
245|              updateNodeData(props.id, { status: "error" });
246|            }
247|          } catch {}
248|        }, 3000);
249|      }
250|    } catch (e) {
251|      setError(e instanceof Error ? e.message : "生成失败");
252|      setLoading(false);
253|      updateNodeData(props.id, { status: "error" });
254|    }
255|  };
256|
257|  // 拖放处理
258|  const handleDrop = (e: React.DragEvent) => {
259|    e.preventDefault();
260|    setDragOver(false);
261|    const file = e.dataTransfer.files[0];
262|    if (file) handleFileUpload(file);
263|  };
264|
265|  return (
266|    <BaseNode {...props}>
267|      <div style={{ position: "relative" }}>
268|        {/* 素材名称标签 - 在预览区外面 */}
269|        <div
270|          style={{
271|            display: "flex",
272|            alignItems: "center",
273|            gap: 4,
274|            padding: "4px 8px 4px 4px",
275|            marginBottom: 4,
276|          }}
277|        >
278|          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.6)" strokeWidth="2">
279|            <polygon points="5 3 19 12 5 21 5 3" />
280|          </svg>
281|          <span style={{ fontSize: 11, color: "rgba(255,255,255,0.8)", fontWeight: 500 }}>{d.assetName || "视频素材"}</span>
282|          {upstream.images.length + upstream.videos.length > 0 && (
283|            <span style={{ fontSize: 9, color: "rgba(255,255,255,0.4)", marginLeft: 4 }}>
284|              ({upstream.images.length + upstream.videos.length}个素材)
285|            </span>
286|          )}
287|        </div>
288|        
289|        {/* 视频预览框 - 纯预览 */}
290|        <div
291|          onClick={() => { selectNodeQuietly(props.id); setShowControlPanel(true); }}
292|          style={{
293|            cursor: "pointer",
294|            background: "#1a1a1a",
295|            transition: "all 0.2s cubic-bezier(0.4, 0, 0.2, 1)",
296|            position: "relative",
297|          }}
298|        >
299|          {previewUrl ? (
300|            <VideoPreview
301|              src={proxyUrl(previewUrl) || previewUrl}
302|              height={previewHeight}
303|              loop
304|              muted
305|              controls
306|              hoverToPlay
307|              onExpand={() => previewUrl && setShowPreview(true)}
308|            />
309|          ) : (
310|            <div
311|              onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
312|              onDragLeave={() => setDragOver(false)}
313|              onDrop={handleDrop}
314|              style={{
315|                height: previewHeight,
316|                display: "flex",
317|                flexDirection: "column",
318|                alignItems: "center",
319|                justifyContent: "center",
320|                gap: 12,
321|                background: dragOver ? "rgba(255,255,255,0.08)" : "transparent",
322|                transition: "all 0.2s",
323|              }}
324|            >
325|              <svg width="48" height="48" viewBox="0 0 48 48" fill="none">
326|                <rect x="6" y="10" width="36" height="28" rx="4" stroke="rgba(255,255,255,0.3)" strokeWidth="2"/>
327|                <path d="M20 18L32 24L20 30V18Z" fill="rgba(255,255,255,0.3)"/>
328|              </svg>
329|              <p style={{ fontSize: 13, color: "#62666d", margin: 0 }}>
330|                拖拽视频到这里，或点击上传
331|              </p>
332|            </div>
333|          )}
334|
335|          {/* 状态指示器 */}
336|          {loading && (
337|            <div style={{
338|              position: "absolute",
