{"content": "1|'use client';
2|
3|import { useEffect, useRef, useState, useCallback } from 'react';
4|
5|interface VideoPreviewProps {
6|  src: string;
7|  poster?: string;
8|  width?: number | string;
9|  height?: number | string;
10|  autoPlay?: boolean;
11|  loop?: boolean;
12|  muted?: boolean;
13|  controls?: boolean;
14|  hoverToPlay?: boolean;
15|  onExpand?: () => void;
16|  className?: string;
17|  style?: React.CSSProperties;
18|}
19|
20|export default function VideoPreview({
21|  src,
22|  poster,
23|  width = '100%',
24|  height = 220,
25|  autoPlay = true,
26|  loop = true,
27|  muted = true,
28|  controls = true,
29|  hoverToPlay = false,
30|  onExpand,
31|  className = '',
32|  style = {},
33|}: VideoPreviewProps) {
34|  const videoRef = useRef<HTMLVideoElement>(null);
35|  const [isHovered, setIsHovered] = useState(false);
36|  const [isLoading, setIsLoading] = useState(true);
37|  const [hasError, setHasError] = useState(false);
38|  const [isPlaying, setIsPlaying] = useState(false);
39|  const [progress, setProgress] = useState(0);
40|  const [duration, setDuration] = useState(0);
41|  const [currentTime, setCurrentTime] = useState(0);
42|  const [volume, setVolume] = useState(muted ? 0 : 1);
43|  const [playbackRate, setPlaybackRate] = useState(1);
44|
45|  // 加载优化
46|  useEffect(() => {
47|    const video = videoRef.current;
48|    if (!video) return;
49|
50|    video.preload = 'auto';
51|
52|    const handleLoadedData = () => {
53|      setIsLoading(false);
54|      setDuration(video.duration);
55|    };
56|
57|    const handleCanPlay = () => {
58|      setIsLoading(false);
59|    };
60|
61|    const handleError = () => {
62|      setHasError(true);
63|      setIsLoading(false);
64|    };
65|
66|    const handleTimeUpdate = () => {
67|      setCurrentTime(video.currentTime);
68|      if (video.duration) {
69|        setProgress((video.currentTime / video.duration) * 100);
70|      }
71|    };
72|
73|    const handlePlay = () => setIsPlaying(true);
74|    const handlePause = () => setIsPlaying(false);
75|
76|    video.addEventListener('loadeddata', handleLoadedData);
