{"content": "1|/**
2| * 媒体代理工具 — 绕过CORS限制
3| * toapis.com的文件服务器没有CORS头，浏览器无法直接播放
4| * 通过后端代理端点获取媒体文件
5| */
6|
7|const PROXY_BASE = 'http://localhost:8000/api/generate/proxy';
8|
9|/**
10| * 将外部媒体URL转换为代理URL
11| * 如果URL已经是本地的（localhost），直接返回
12| */
13|export function proxyUrl(url: string | null): string {
14|  if (!url) return '';
15|  // 本地URL不需要代理
16|  if (url.startsWith('http://localhost') || url.startsWith('blob:') || url.startsWith('data:')) {
17|    return url;
18|  }
19|  // 外部URL走代理
20|  return `${PROXY_BASE}?url=${encodeURIComponent(url)}`;
21|}
