{"content": "1|import { create } from "zustand";
2|import type { Node, Edge, OnNodesChange, OnEdgesChange, Connection } from "@xyflow/react";
3|import { applyNodeChanges, applyEdgeChanges, addEdge } from "@xyflow/react";
4|import type { NodeData } from "@/types/workflow";
5|import { MAX_UNDO_STEPS } from "@/lib/constants";
6|
7|interface Snapshot {
8|  nodes: Node<NodeData>[];
9|  edges: Edge[];
10|}
11|
12|interface ViewportPosition {
13|  x: number;
14|  y: number;
15|  zoom: number;
16|}
17|
18|interface WorkflowState {
19|  nodes: Node<NodeData>[];
20|  edges: Edge[];
21|  selectedNodeId: string | null;
22|  propertyPanelOpen: boolean;
23|  executionPanelOpen: boolean;
24|  miniMapVisible: boolean;
25|  undoStack: Snapshot[];
26|  redoStack: Snapshot[];
27|  workflowName: string;
28|  isInitialized: boolean;
29|  viewport: ViewportPosition;
30|  showControlPanel: boolean;
31|
32|  onNodesChange: OnNodesChange;
33|  onEdgesChange: OnEdgesChange;
34|  onConnect: (connection: Connection) => void;
35|  addNode: (node: Node<NodeData>) => void;
36|  removeNode: (nodeId: string) => void;
37|  removeEdge: (edgeId: string) => void;
38|  updateNodeData: (nodeId: string, data: Partial<NodeData>) => void;
39|  selectNode: (nodeId: string | null) => void;
40|  selectNodeQuietly: (nodeId: string | null) => void;
41|  updateViewport: (viewport: ViewportPosition) => void;
42|  setShowControlPanel: (show: boolean) => void;
43|  togglePropertyPanel: () => void;
44|  toggleExecutionPanel: () => void;
45|  toggleMiniMap: () => void;
46|  undo: () => void;
47|  redo: () => void;
48|  saveSnapshot: () => void;
49|  clearWorkflow: () => void;
50|  loadWorkflow: (nodes: Node<NodeData>[], edges: Edge[], name?: string) => void;
51|  initializeWorkflow: () => void;
52|}
53|
54|const STORAGE_KEY = "antoken-workflow";
55|
56|function saveToStorage(state: Pick<WorkflowState, "nodes" | "edges" | "workflowName">) {
57|  try {
58|    localStorage.setItem(STORAGE_KEY, JSON.stringify({
59|      nodes: state.nodes,
60|      edges: state.edges,
61|      workflowName: state.workflowName,
62|    }));
63|  } catch { /* quota exceeded */ }
64|}
65|
66|function loadFromStorage(): { nodes: Node<NodeData>[]; edges: Edge[]; workflowName: string } | null {
67|  try {
68|    const raw = localStorage.getItem(STORAGE_KEY);
69|    if (!raw) return null;
70|    return JSON.parse(raw);
71|  } catch {
72|    return null;
73|  }
74|}
75|
76|export const useWorkflowStore = create<WorkflowState>((set, get) => ({
77|  nodes: [],
78|  edges: [],
79|  selectedNodeId: null,
80|  propertyPanelOpen: false,
81|  executionPanelOpen: false,
82|  miniMapVisible: true,
83|  undoStack: [],
84|  redoStack: [],
85|  workflowName: "Untitled Workflow",
86|  isInitialized: false,
87|  viewport: { x: 0, y: 0, zoom: 1 },
88|  showControlPanel: false,
89|
90|  setShowControlPanel: (show) => set({ showControlPanel: show }),
91|
92|  initializeWorkflow: () => {
93|    if (get().isInitialized) return;
94|    const saved = loadFromStorage();
95|    if (saved && saved.nodes.length > 0) {
96|      set({
97|        nodes: saved.nodes,
98|        edges: saved.edges,
99|        workflowName: saved.workflowName,
100|        isInitialized: true,
101|      });
102|    } else {
103|      set({ isInitialized: true });
104|    }
105|  },
106|
107|  onNodesChange: (changes) => {
108|    set((s) => {
109|      const updated = applyNodeChanges(changes, s.nodes) as Node<NodeData>[];
110|      saveToStorage({ nodes: updated, edges: s.edges, workflowName: s.workflowName });
111|      return { nodes: updated };
112|    });
113|  },
114|
115|  onEdgesChange: (changes) => {
116|    set((s) => {
117|      // 只应用select类型的变更
118|      // 过滤remove和replace类型，防止ReactFlow自动删除/替换边
119|      const filteredChanges = changes.filter((c) => c.type === 'select');
120|      if (filteredChanges.length === 0) return s;
121|      const updated = applyEdgeChanges(filteredChanges, s.edges);
122|      saveToStorage({ nodes: s.nodes, edges: updated, workflowName: s.workflowName });
123|      return { edges: updated };
124|    });
125|  },
126|
127|  onConnect: (connection) => {
128|    // 只禁止自连接
129|    if (connection.source === connection.target) return;
130|    console.log('[onConnect] 新连接:', connection);
131|    console.log('[onConnect] 当前边数:', get().edges.length);
132|
133|    set((s) => {
134|      // 生成唯一ID
135|      const edgeId = `edge-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
136|      const newEdge = {
137|        id: edgeId,
138|        source: connection.source,
139|        target: connection.target,
140|        sourceHandle: connection.sourceHandle || null,
141|        targetHandle: connection.targetHandle || null,
142|        animated: false,
143|        style: { stroke: "rgba(255,255,255,0.4)", strokeWidth: 1.5 },
144|        type: "bezier",
145|      };
146|      // 直接追加，不用addEdge
147|      const updated = [...s.edges, newEdge];
148|      saveToStorage({ nodes: s.nodes, edges: updated, workflowName: s.workflowName });
149|      return { edges: updated };
150|    });
151|  },
152|
153|  addNode: (node) => {
154|    get().saveSnapshot();
155|    set((s) => {
156|      const updated = [...s.nodes, node];
157|      saveToStorage({ nodes: updated, edges: s.edges, workflowName: s.workflowName });
158|      return { nodes: updated };
159|    });
160|  },
161|
162|  updateViewport: (viewport) => {
163|    set({ viewport });
164|  },
165|
166|  removeNode: (nodeId) => {
167|    get().saveSnapshot();
168|    set((s) => {
169|      const nodes = s.nodes.filter((n) => n.id !== nodeId);
170|      const edges = s.edges.filter((e) => e.source !== nodeId && e.target !== nodeId);
171|      saveToStorage({ nodes, edges, workflowName: s.workflowName });
172|      return {
173|        nodes,
174|        edges,
175|        selectedNodeId: s.selectedNodeId === nodeId ? null : s.selectedNodeId,
176|        propertyPanelOpen: s.selectedNodeId === nodeId ? false : s.propertyPanelOpen,
177|      };
178|    });
179|  },
180|
181|  removeEdge: (edgeId) => {
182|    get().saveSnapshot();
183|    set((s) => {
184|      const edges = s.edges.filter((e) => e.id !== edgeId);
185|      saveToStorage({ nodes: s.nodes, edges, workflowName: s.workflowName });
186|      return { edges };
187|    });
188|  },
189|
190|  updateNodeData: (nodeId, data) => {
191|    // 只在状态变更时保存快照（避免轮询时过多快照）
192|    if (data.status === "success" || data.status === "error") {
193|      get().saveSnapshot();
194|    }
195|    set((s) => {
196|      const nodes = s.nodes.map((n) =>
197|        n.id === nodeId ? { ...n, data: { ...n.data, ...data } } : n
198|      ) as Node<NodeData>[];
199|      saveToStorage({ nodes, edges: s.edges, workflowName: s.workflowName });
200|      return { nodes };
201|    });
202|  },
203|
204|  selectNode: (nodeId) => {
205|    set({ selectedNodeId: nodeId, propertyPanelOpen: nodeId !== null });
206|  },
207|
208|  selectNodeQuietly: (nodeId) => {
209|    set({ selectedNodeId: nodeId });
210|  },
