{"content":""use client";

import React, { useCallback, useRef, useState, useMemo } from "react";
import {
  ReactFlow,
  ReactFlowProvider,
  MiniMap,
  Controls,
  Background,
  BackgroundVariant,
  type Node,
  type Edge,
  type NodeMouseHandler,
  type EdgeMouseHandler,
  useReactFlow,
  type OnConnect,
  ConnectionMode,
  PanOnScrollMode,
} from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import { nodeTypes } from "@/components/nodes";
import { useWorkflowStore } from "@/stores/workflowStore";
import type { NodeData, NodeFlowType } from "@/types/workflow";

// 获取下一个素材编号
function getNextAssetNumber(type: 'IMAGE' | 'VIDEO'): number {
  const key = `antoken_asset_counter_${type}`;
  const current = parseInt(localStorage.getItem(key) || '0', 10);
  const next = current + 1;
  localStorage.setItem(key, next.toString());
  return next;
}

function CanvasInner() {
  const {
    nodes, edges, onNodesChange, onEdgesChange, onConnect,
    selectNode, miniMapVisible, addNode, removeNode, removeEdge, updateViewport,
    setShowControlPanel, selectedNodeId,
  } = useWorkflowStore();

  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const { screenToFlowPosition } = useReactFlow();
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 右键菜单状态
  const [contextMenu, setContextMenu] = useState<{
    x: number; y: number; type: 'edge' | 'canvas'; edgeId?: string;
  } | null>(null);

  // 当前添加素材的类型
  const [addingAssetType, setAddingAssetType] = useState<'IMAGE' | 'VIDEO' | null>(null);

  const onPaneClick = useCallback(() => {
    selectNode(null);
    setContextMenu(null);
  }, [selectNode]);

  const onMove = useCallback((_: any, viewport: { x: number; y: number; zoom: number }) => {
    updateViewport(viewport);
  }, [updateViewport]);

  // 边右键菜单
  const onEdgeContextMenu: EdgeMouseHandler = useCallback((e, edge) => {
    e.preventDefault();
    setContextMenu({ x: e.clientX, y: e.clientY, type: 'edge', edgeId: edge.id });
  }, []);

  // 画布右键菜单
  const onPaneContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setContextMenu({ x: e.clientX, y: e.clientY, type: 'canvas' });
  }, []);

  // 删除边
  const handleDeleteEdge = useCallback(() => {
    if (contextMenu?.edgeId) {
      removeEdge(contextMenu.edgeId);
      setContextMenu(null);
    }
  }, [contextMenu, removeEdge]);

  // 添加素材到画布
  const handleAddAsset = useCallback((assetType: 'IMAGE' | 'VIDEO') => {
    setAddingAssetType(assetType);
    setContextMenu(null);
    // 触发文件选择
    if (fileInputRef.current) {
      fileInputRef.current.accept = assetType === 'IMAGE' ? 'image/*' : 'video/*';
      fileInputRef.current.click();
    }
  }, []);

  // 处理文件选择
  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !addingAssetType) return;

    // 创建本地URL（不修改文件）
    const fileUrl = URL.createObjectURL(file);

    // 获取文件的原始尺寸
    if (addingAssetType === 'IMAGE') {
      const img = new window.Image();
      img.onload = () => {
        // 创建图片节点，保持原始尺寸
        createAssetNode(addingAssetType, fileUrl, file.name, {
          width: img.naturalWidth,
          height: img.naturalHeight,
        });
      };
      img.src = fileUrl;
    } else {
      // 视频节点
      const video = document.createElement('video');
      video.onloadedmetadata = () => {
        createAssetNode(addingAssetType, fileUrl, file.name, {
          width: video.videoWidth,
          height: video.videoHeight,
          duration: video.duration,
        });
      };
      video.src = fileUrl;
    }

    // 重置input
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    setAddingAssetType(null);
  }, [addingAssetType]);

  // 创建素材节点
  const createAssetNode = useCallback((
    assetType: 'IMAGE' | 'VIDEO',
    fileUrl: string,
    fileName: string,
    originalMeta: { width: number; height: number; duration?: number }
  ) => {
    const assetNumber = getNextAssetNumber(assetType);
    const assetName = assetType === 'IMAGE' ? `图素材${assetNumber}` : `视频素材${assetNumber}`;

    // 计算节点位置（视口中心）
    const centerX = (-updateViewport.x + window.innerWidth / 2) / 1;
    const centerY = (-updateViewport.y + window.innerHeight / 2) / 1;

    const newNode: Node<NodeData> = {
      id: `${assetType}_${Date.now()}`,
      type: assetType,
      position: { x: centerX - 140, y: centerY - 100 },
      data: {
        label: assetType === 'IMAGE' ? '图片素材' : '视频素材',
        category: 'INPUT',
        nodeType: assetType,
        description: `用户上传的${assetType === 'IMAGE' ? '图片' : '视频'}素材`,
        config: {
          assetUrl: fileUrl,
          assetName,
          originalWidth: originalMeta.width,
          originalHeight: originalMeta.height,
          originalDuration: originalMeta.duration,
          isLocalAsset: true, // 标记为本地素材
        },
        assetName,
        assetUrl: fileUrl,
        assetType,
      } as NodeData,
    };

    addNode(newNode);
  }, [addNode, updateViewport]);

  // 点击其他地方关闭菜单
  const handlePaneClick = useCallback(() => {
    selectNode(null);
    setContextMenu(null);
    setShowControlPanel(false);
  }, [selectNode, setShowControlPanel]);

  const onDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
  }, []);

  const onDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      const type = e.dataTransfer.getData("application/antoken-node");
      if (!type || !reactFlowWrapper.current) return;

      try {
        const nodeDef = JSON.parse(e.dataTransfer.getData("application/antoken-nodedef"));
        const position = screenToFlowPosition({
          x: e.clientX,
          y: e.clientY,
        });

        const newNode: Node<NodeData> = {
          id: `${type}_${Date.now()}`,
          type: nodeDef.flowType ?? "baseNode",
          position: {
            x: position.x - 100,
            y: position.y - 50,
          },
          data: {
            label: nodeDef.label,
            category: nodeDef.category,
            nodeType: type as NodeFlowType,
            description: nodeDef.description ?? "",
            inputs: nodeDef.inputs ?? [],
            outputs: nodeDef.outputs ?? [],
            config: nodeDef.defaultConfig ?? {},
          },
        };

        addNode(newNode);
      } catch (err) {
        console.error("Failed to drop node:", err);
      }
    },
    [addNode, screenToFlowPosition]
  );

  const nodeColor = useCallback((node: Node) => {
    const d = node.data as unknown as NodeData;
    const colors: Record<string, string> = {
      INPUT: "rgba(255,255,255,0.05)",
      AI_GENERATION: "rgba(255,255,255,0.05)",
      PROCESSING: "rgba(255,255,255,0.05)",
      OUTPUT: "rgba(255,255,255,0.05)",
    };
    return colors[d.category] ?? "rgba(255,255,255,0.05)";
  }, []);

  const [snapEnabled, setSnapEnabled] = useState(false);

  const snapGridValue: [number, number] = useMemo(() => [16, 16], []);

  const defaultEdgeOpts = useMemo(() => ({
    animated: false,
    style: { 
      stroke: "rgba(255,255,255,0.2)", 
      strokeWidth: 1.5, 
    },
    type: "bezier" as const,
  }), []);

  const connLineStyle = useMemo(() => ({
    stroke: "rgba(255,255,255,0.4)", 
    strokeWidth: 1.5, 
  }), []);

  const bgStyle = useMemo(() => ({ background: "#000" }), []);
  const miniMapStyle = useMemo(() => ({
    background: "#0f1011",
    border: "1px solid rgba(255,255,255,0.08)",
    borderRadius: 8,
  }), []);

  const proOpts = useMemo(() => ({ hideAttribution: true }), []);
  const defaultVP = useMemo(() => ({ x: 0, y: 0, zoom: 1 }), []);

  return (
    <div
      ref={reactFlowWrapper}
      className="w-full h-full"
      onDragOver={onDragOver}
      onDrop={onDrop}
    >
      <ReactFlow
        nodes={nodes}
        edges={edges.map(edge => {
          // 获取所有下游节点
          const getDownstreamNodes = (nodeId: string): string[] => {
            const directTargets = edges.filter(e => e.source === nodeId).map(e => e.target);
            const allTargets = [...directTargets];
            directTargets.forEach(targetId => {
              allTargets.push(...getDownstreamNodes(targetId));
            });
            return allTargets;
          };

          const isHighlighted = selectedNodeId && (
            edge.source === selectedNodeId || 
            edge.target === selectedNodeId ||
            getDownstreamNodes(selectedNodeId).includes(edge.source) ||
            getDownstreamNodes(selectedNodeId).includes(edge.target)
          );

          return {
            ...edge,
            style: {
              ...edge.style,
              stroke: isHighlighted ? "#ffffff" : "rgba(255,255,255,0.2)",
              strokeWidth: isHighlighted ? 2 : 1.5,
            },
          };
        })}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onPaneClick={handlePaneClick}
        onPaneContextMenu={onPaneContextMenu}
        onEdgeContextMenu={onEdgeContextMenu}
        onMove={onMove}
        nodeTypes={nodeTypes}
        connectionMode={ConnectionMode.Loose}
        fitView
        snapToGrid={snapEnabled}
        snapGrid={snapGridValue}
        defaultEdgeOptions={defaultEdgeOpts}
        connectionLineStyle={connLineStyle}
        proOptions={proOpts}
        minZoom={0.2}
        maxZoom={3}
        defaultViewport={defaultVP}
        // 画布移动优化
        panOnDrag={true}
        panOnScroll={true}
        panOnScrollSpeed={1}
        panOnScrollMode={PanOnScrollMode.Free}
        zoomOnScroll={true}
        zoomOnPinch={true}
        zoomOnDoubleClick={false}
        preventScrolling={true}
        autoPanOnNodeDrag={true}
        autoPanOnConnect={true}
      >
        <Background
          variant={BackgroundVariant.Dots}
          gap={32}
          size={2}
          color="rgba(255,255,255,0.15)"
          style={bgStyle}
        />
        {miniMapVisible && (
          <MiniMap
            nodeColor={nodeColor}
            nodeStrokeColor="rgba(255,255,255,0.08)"
            maskColor="rgba(94,106,210,0.06)"
            style={miniMapStyle}
          />
        )}
        <Controls showInteractive={false} />
      </ReactFlow>

      {/* 隐藏的文件输入 */}
      <input
        ref={fileInputRef}
        type="file"
        style={{ display: 'none' }}
        onChange={handleFileSelect}
      />

      {/* 吸附网格开关 */}
      <button
        onClick={() => setSnapEnabled(!snapEnabled)}
        style={{
          position: "absolute",
          bottom: 80,
          left: 12,
          width: 32,
          height: 32,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          background: snapEnabled ? "var(--accent-bright, #5e6ad2)" : "var(--bg-elevated, #191a1b)",
          border: "1px solid rgba(255,255,255,0.1)",
          borderRadius: 6,
          color: snapEnabled ? "#fff" : "#8a8f98",
          cursor: "pointer",
          fontSize: 14,
          zIndex: 5,
        }}
        title={snapEnabled ? "关闭网格吸附" : "开启网格吸附"}
      >
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path d="M2 2h4v4H2V2zm0 8h4v4H2v-4zm8-8h4v4h-4V2zm0 8h4v4h-4v-4z" stroke="currentColor" strokeWidth="1.5" fill="none"/>
        </svg>
      </button>

      {/* 右键菜单 */}
      {contextMenu && (
        <div
          style={{
            position: "fixed",
            left: contextMenu.x,
            top: contextMenu.y,
            background: "#191a1b",
            border: "1px solid rgba(255,255,255,0.1)",
            borderRadius: 8,
            padding: "4px 0",
            zIndex: 1000,
            minWidth: 160,
            boxShadow: "0 4px 12px rgba(0,0,0,0.5)",
            backdropFilter: "blur(12px)",
          }}
          onClick={(e) => e.stopPropagation()}
        >
          {contextMenu.type === 'edge' ? (
            // 边右键菜单
            <button
              onClick={handleDeleteEdge}
              style={{
                display: "block",
                width: "100%",
                padding: "8px 14px",
                fontSize: 12,
                color: "#ef4444",
                background: "none",
                border: "none",
                cursor: "pointer",
                textAlign: "left",
                borderRadius: 4,
              }}
              onMouseEnter={(e) => e.currentTarget.style.background = "rgba(239,68,68,0.1)"}
              onMouseLeave={(e) => e.currentTarget.style.background = "none"}
            >
              删除连接线
            </button>
          ) : (
            // 画布右键菜单
            <>
              <div style={{ padding: "6px 14px 4px", fontSize: 10, color: "#62666d" }}>
                添加素材
              </div>
              <button
                onClick={() => handleAddAsset('IMAGE')}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  width: "100%",
                  padding: "8px 14px",
                  fontSize: 12,
                  color: "#d0d6e0",
                  background: "none",
                  border: "none",
                  cursor: "pointer",
                  textAlign: "left",
                  borderRadius: 4,
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = "rgba(255,255,255,0.05)"}
                onMouseLeave={(e) => e.currentTarget.style.background = "none"}
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>
                  <circle cx="8.5" cy="8.5" r="1.5"/>
                  <polyline points="21 15 16 10 5 21"/>
                </svg>
                图片素材
              </button>
              <button
                onClick={() => handleAddAsset('VIDEO')}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  width: "100%",
                  padding: "8px 14px",
                  fontSize: 12,
                  color: "#d0d6e0",
                  background: "none",
                  border: "none",
                  cursor: "pointer",
                  textAlign: "left",
                  borderRadius: 4,
                }}
                onMouseEnter={(e) => e.currentTarget.style.background = "rgba(255,255,255,0.05)"}
                onMouseLeave={(e) => e.currentTarget.style.background = "none"}
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <polygon points="5 3 19 12 5 21 5 3"/>
                </svg>
                视频素材
              </button>
            </>
          )}
        </div>
      )}

      {/* 空状态 */}
      {nodes.length === 0 && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="text-center">
            <p className="text-sm" style={{ color: "#62666d" }}>
              从左侧点击节点添加到画布，或右键画布添加素材
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

export default function WorkflowCanvas() {
  return (
    <ReactFlowProvider>
      <CanvasInner />
    </ReactFlowProvider>
  );
}
