{"content":"/**
 * toapis.com 直连客户端
 * 前端直接调用toapis API，不经过后端代理
 */

// Asset API端点
const ASSET_GROUP_URL = "/videos/doubao-seedance-2-0/private-avatar/groups";
const ASSET_UPLOAD_URL = "/videos/doubao-seedance-2-0/private-avatar/assets";

interface ToapisConfig {
  apiUrl: string;
  apiKey: string;
}

function headers(config: ToapisConfig, extra?: Record<string, string>): Record<string, string> {
  return {
    "Authorization": `Bearer ${config.apiKey}`,
    ...extra,
  };
}

/**
 * 创建Asset Group
 */
export async function createAssetGroup(config: ToapisConfig): Promise<string> {
  const resp = await fetch(`${config.apiUrl}${ASSET_GROUP_URL}`, {
    method: "POST",
    headers: headers(config, { "Content-Type": "application/json" }),
    body: JSON.stringify({ name: "antoken-composite" }),
  });
  if (!resp.ok) throw new Error(`创建Group失败: ${resp.text}`);
  const data = await resp.json();
  const groupId = data?.data?.group_id;
  if (!groupId) throw new Error(`未返回group_id: ${JSON.stringify(data)}`);
  return groupId;
}

/**
 * 上传素材（URL方式）
 */
export async function uploadAssetByUrl(
  config: ToapisConfig,
  groupId: string,
  sourceUrl: string,
  assetType: "image" | "video"
): Promise<string> {
  const resp = await fetch(`${config.apiUrl}${ASSET_UPLOAD_URL}`, {
    method: "POST",
    headers: headers(config, { "Content-Type": "application/json" }),
    body: JSON.stringify({
      group_id: groupId,
      source_url: sourceUrl,
      asset_type: assetType,
    }),
  });
  if (!resp.ok) throw new Error(`上传素材失败: ${resp.text}`);
  const data = await resp.json();
  const assetId = data?.data?.asset_id;
  if (!assetId) throw new Error(`未返回asset_id: ${JSON.stringify(data)}`);
  return assetId;
}

/**
 * 上传素材（二进制文件方式）
 */
export async function uploadAssetByFile(
  config: ToapisConfig,
  groupId: string,
  file: File,
  assetType: "image" | "video"
): Promise<string> {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("group_id", groupId);
  formData.append("asset_type", assetType);

  const resp = await fetch(`${config.apiUrl}${ASSET_UPLOAD_URL}`, {
    method: "POST",
    headers: headers(config),
    body: formData,
  });
  if (!resp.ok) throw new Error(`上传素材失败: ${resp.text}`);
  const data = await resp.json();
  const assetId = data?.data?.asset_id;
  if (!assetId) throw new Error(`未返回asset_id: ${JSON.stringify(data)}`);
  return assetId;
}

/**
 * 等待asset变为active
 */
export async function waitAssetActive(
  config: ToapisConfig,
  assetId: string,
  maxWait: number = 60
): Promise<boolean> {
  for (let i = 0; i < maxWait / 2; i++) {
    const resp = await fetch(`${config.apiUrl}${ASSET_UPLOAD_URL}/${assetId}`, {
      headers: headers(config),
    });
    if (resp.ok) {
      const data = await resp.json();
      const status = data?.data?.status;
      if (status === "active") return true;
      if (status === "failed") throw new Error(`Asset处理失败: ${assetId}`);
    }
    await new Promise((r) => setTimeout(r, 2000));
  }
  throw new Error(`Asset激活超时: ${assetId}`);
}

/**
 * 完整流程：上传素材 -> 等待active -> 返回asset_id
 */
export async function prepareAsset(
  config: ToapisConfig,
  groupId: string,
  source: string | File,
  assetType: "image" | "video"
): Promise<string> {
  let assetId: string;
  if (source instanceof File) {
    assetId = await uploadAssetByFile(config, groupId, source, assetType);
  } else {
    assetId = await uploadAssetByUrl(config, groupId, source, assetType);
  }
  await waitAssetActive(config, assetId);
  return assetId;
}

/**
 * 创建视频生成任务
 */
export async function createVideoTask(
  config: ToapisConfig,
  params: {
    prompt: string;
    model: string;
    duration: number;
    ratio?: string;
    image_with_roles?: Array<{ url: string; role: string }>;
    video_with_roles?: Array<{ url: string; role: string }>;
  }
): Promise<{ task_id: string }> {
  const resp = await fetch(`${config.apiUrl}/generate/video`, {
    method: "POST",
    headers: headers(config, { "Content-Type": "application/json" }),
    body: JSON.stringify(params),
  });
  if (!resp.ok) throw new Error(`创建视频任务失败: ${resp.text}`);
  const data = await resp.json();
  const taskId = data?.data?.task_id;
  if (!taskId) throw new Error(`未返回task_id: ${JSON.stringify(data)}`);
  return { task_id: taskId };
}

/**
 * 创建图片生成任务
 */
export async function createImageTask(
  config: ToapisConfig,
  params: {
    prompt: string;
    model: string;
    size?: string;
    image_with_roles?: Array<{ url: string; role: string }>;
  }
): Promise<{ task_id: string }> {
  const resp = await fetch(`${config.apiUrl}/generate/image`, {
    method: "POST",
    headers: headers(config, { "Content-Type": "application/json" }),
    body: JSON.stringify(params),
  });
  if (!resp.ok) throw new Error(`创建图片任务失败: ${resp.text}`);
  const data = await resp.json();
  const taskId = data?.data?.task_id;
  if (!taskId) throw new Error(`未返回task_id: ${JSON.stringify(data)}`);
  return { task_id: taskId };
}

/**
 * 轮询任务状态
 */
export async function pollTask(
  config: ToapisConfig,
  taskType: "video" | "image",
  taskId: string
): Promise<{ status: string; progress: number; url?: string; asset_id?: string; error?: string }> {
  const resp = await fetch(`${config.apiUrl}/task/${taskType}/${taskId}`, {
    headers: headers(config),
  });
  if (!resp.ok) throw new Error(`轮询失败: ${resp.text}`);
  const data = await resp.json();
  return {
    status: data?.data?.status || "unknown",
    progress: data?.data?.progress || 0,
    url: data?.data?.output?.url || data?.data?.url,
    asset_id: data?.data?.asset_id,
    error: data?.data?.error,
  };
}

/**
 * 获取可用模型列表
 */
export async function getModels(config: ToapisConfig): Promise<string[]> {
  const resp = await fetch(`${config.apiUrl}/models`, {
    headers: headers(config),
  });
  if (!resp.ok) throw new Error(`获取模型失败: ${resp.text}`);
  const data = await resp.json();
  return data?.data?.models || [];
}
