19|      }
20|      // Ctrl+Shift+Z / Cmd+Shift+Z or Ctrl+Y
21|      if ((e.ctrlKey || e.metaKey) && ((e.key === "z" && e.shiftKey) || e.key === "y")) {
22|        e.preventDefault();
23|        redo();
